writeFileSync\(path.join\(out, "rich-text.tsx"\), load\("lib/rich-text.tsx"\).replace\(/from "react"/, 'from "node:util"'\)\);
writeFileSync\(path.join\(out, "editor-types.ts"\), load\("components/admin/editor-types.ts"\)\);

