withCustom.tabs.splice\(8, 0, { key: "maintenance", label: "Maintenance", isCustom: true, enabled: true, heading: "Maintenance Features", intro: "<p>Service every <strong>500</strong> hours.</p>", features: [{ label: "Interval", text: "500 hours" }, { label: "", text: "Grease bearings" }, { label: "", text: "Inspect seals" }] }\);
withCustom.tabs.unshift\({ key: "6b1f0a3e-1111-4111-8111-111111111111", label: "Working Principle", isCustom: true, enabled: false, heading: "", intro: "", features: [] }\);
withCustom.tabs[0].features.push\({ label: "", text: "Two lobes rotate" }\);

const payload = toPayload\(withCustom\);
assert\(payload.tabs.length === 10, "payload keeps all 10 tabs"\);
assert\(payload.tabs[0].label === "Working Principle" && payload.tabs[0].sortOrder === 0, "custom tab first, order 0"\);
assert\(payload.tabs.find\(\(t\) => t.key === "maintenance"\).features.length === 3, "3 bullets saved on Maintenance"\);
assert\(payload.tabs.find\(\(t\) => t.key === "series"\).label === "Series", "standard tab label preserved"\);

// 3. Server round-trip shape \(what admin GET returns\) -> editor normalizes back.
