const reloaded = normalizeTechnical\({ tabs: serverTabs, performance: { columns: [], rows: [] }, materials: [], paragraphs: [] }\);
assert\(reloaded.tabs.map\(\(t\) => t.label\).join\(","\) === withCustom.tabs.map\(\(t\) => t.label\).join\(","\), "edit product restores tab order and names"\);
assert\(reloaded.tabs.find\(\(t\) => t.key === "maintenance"\).intro.includes\("<strong>500</strong>"\), "rich text restored"\);
assert\(reloaded.tabs.filter\(\(t\) => !t.isCustom\).length === 8, "8 standard tabs still there after reload"\);

