    const h = document.getElementById\("exploration-heading"\);
    const sec = h.closest\("section"\);
    const grid = h.parentElement.parentElement;
    const hcs = getComputedStyle\(h\);
    const probe = document.createElement\("span"\);
    probe.style.cssText = `position:absolute;visibility:hidden;white-space:nowrap;font:${hcs.fontWeight} ${hcs.fontSize}/${hcs.lineHeight} ${hcs.fontFamily};letter-spacing:${hcs.letterSpacing}`;
    probe.textContent = h.textContent.trim\(\);
    document.body.appendChild\(probe\);
    const textW = probe.getBoundingClientRect\(\).width;
    probe.remove\(\);
    const left = h.parentElement.getBoundingClientRect\(\);
    const btn = sec.querySelector\("a"\).getBoundingClientRect\(\);
    return { section: Math.round\(sec.getBoundingClientRect\(\).width\), gridCols: getComputedStyle\(grid\).gridTemplateColumns, textCol: Math.round\(left.width\), textW: Math.round\(textW\), lines: Math.round\(h.getBoundingClientRect\(\).height / parseFloat\(hcs.lineHeight\)\), font: hcs.fontSize, btnW: Math.round\(btn.width\), overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth };
  }\);
  console.log\(vw, JSON.stringify\(m\)\);
  await page.close\(\);
}
await browser.close\(\);
